import json
n=17; center=n//2
G=[]
for r in range(n):
 row=[0]*n
 if r<=center:
  row[center-r]=2
  row[center+r]=2
 if r>=3:
  lo=max(0,center-(r-2)); hi=min(n-1,center+(r-2))
  for c in range(lo,hi+1):
   if (c-r-center)%4==0 and row[c]==0:
    row[c]=1
 G.append(row)
